  /**
   * The offset or length of the substring in UTF-16 encoding.
   *
   * Primary encoding used by .NET, Java, and JavaScript.
   */
  utf16: number;
  /**
   * The offset or length of the substring in CodePoint encoding.
   *
   * Primary encoding used by Python.
   */
  codePoint: number;
}

